////
/// Accordion gallery
/// @group patterns
////
.accordion--gallery__container {
    @include media('<tablet') {
        display: none;
    }

    // edge case for when there is only one accordion item
    &[data-count='1'] {
        display: block;

        // hide the carousel gallery when there is only one accordion item
        & + .carousel-gallery-default {
            display: none;
        }

        .accordion__heading {
            @include betatype();
            padding-left: $measure--basic;
        }

        @include media('<tablet') {
            .accordion--gallery {
                flex-direction: column;
            }

            .accordion--gallery__images ul,
            .accordion--gallery__heading,
            .accordion__heading,
            .accordion__body {
                margin-left: 0;
                padding-left: 0;
            }
        }
    }
}

.js .accordion--gallery__container {
    & + .carousel-gallery-default {
        background: $color-zinc60;

        @include media('>=tablet') {
            display: none;
        }
    }
}

.accordion--gallery {
    display: flex;
    flex-direction: row;
    margin-bottom: $measure--small4;

    > div {
        flex: 1;
    }
}

.accordion--gallery__images {
    ul {
        position: relative;
        overflow: hidden;
        height: 100%;
        margin-left: $measure--small4;
    }

    li {
        &[data-active='true'] {
            height: 100%;
            opacity: 1;
        }

        opacity: 0;
        height: 0;
        margin: 0;
        transition: opacity 1s ease-in-out;
        position: relative;
        overflow: hidden;
        display: block;

        figure {
            position: relative;
            display: flex;
            overflow: hidden;
            border-radius: $measure--quarter;

            picture {
                line-height: 0;
            }

            img {
                transition: transform 0.6s;
            }

            &:hover {
                @include media('hover') {
                    img {
                        transform: scale(1.03);
                    }

                    .accordion-image-veil {
                        opacity: 1;
                    }
                }
            }

            .accordion-image-veil {
                margin-top: 0;
                position: absolute;
                width: 100%;
                height: 100%;
                background: linear-gradient(
                    180deg,
                    rgba(0, 0, 0, 0.2) 0%,
                    rgba(0, 0, 0, 0.4) 100%
                );
                content: '';
                z-index: z-index('above');
                opacity: 0;
                transition: opacity 0.15s;
                display: flex;
                align-items: center;
                align-items: flex-end;

                p {
                    width: 100%;
                    margin-bottom: $measure--basic;
                    text-align: center;
                    color: $color-purewhite;
                }
            }
        }
    }

    .youtube-video {
        height: 0;
        padding-bottom: 56.25%;
        position: relative;
        width: 100%;

        iframe {
            height: 100%;
            left: 0;
            margin: 0;
            position: absolute;
            top: 0;
            width: 100%;
        }
    }
}

.courses-v26--ug__facilities {
    background: $color-zinc60;
    color: $color-purewhite;
}

.courses-v26--ug__facilities__heading,
.accordion--gallery__heading {
    padding-left: $measure--basic;
    font-weight: $font-weight-thin;
}

// override carousel-gallery styles for facilities section
.courses-v26--ug__facilities .carousel-gallery {
    h2,
    h3,
    h4 {
        font-weight: $font-weight-thin;
    }
}

.accordion--gallery__container {
    padding: $measure--basic;
}

.accordion--gallery__container:not([data-count='1']) {
    @include media('<tablet') {
        padding: 0;
    }
}

// facilities styles
.courses-v26--ug__facilities__video {
    @include media('>tablet') {
        display: grid;
        grid-template-columns: 1fr 2fr;
        grid-column-gap: $measure--basic;
    }
}

.courses-v26--ug__facilities__video__intro {
    @include media('>tablet') {
        padding: $measure--small4 0;
        p {
            margin: 0;
        }
    }
}

.embedded-video {
    @include media('<=tablet') {
        padding-top: 0;
    }
}
.courses-v26--ug__facilities[data-type='video'] {
    .courses-v26--ug__facilities__container {
        padding: $measure--basic;
    }

    .courses-v26--ug__facilities__heading {
        padding-left: 0;
    }

    figcaption {
        color: $color-purewhite;
    }
}
