.card--testimonial-v26 {
    border-top: $border-width-thicker solid $color-nearblack;
    padding-top: $measure--basic;
    &.card {
        // specific to override the .card rule
        margin: 0;
    }

    &__video {
    }
    &__quote {
        margin: 0;
        padding-top: 0;
        p {
            @include deltatype();
            &:after {
                content: '"';
                padding-left: $measure--quarter;
            }
        }
    }
    .embedded-video-v26 {
        padding: 0;
    }

    &__author {
        display: flex;
        gap: $measure--threequarters;
        @include extrasmalltype();
    }

    &__thumbnail {
        display: block;
        width: $measure--medium2;
        height: $measure--medium2;
        border-radius: $border-radius-round;
    }
    &__name {
        color: $color-red50;
        display: block;
        font-weight: $font-weight-bold;
    }
    &__caption {
        @include extrasmalltype();
        font-weight: $font-weight-bold;
    }
}
